def canonical_form(word):
    """Return canonical form of word based on letter positions"""
    mapping = {}
    result = []
    counter = 0
    for c in word:
        if c not in mapping:
            mapping[c] = counter
            counter += 1
        result.append(mapping[c])
    return tuple(result)

# Group words by canonical form
from collections import defaultdict
groups = defaultdict(list)
for w in valid_words_len4plus:
    groups[canonical_form(w)].append(w)

print(f"Number of groups: {len(groups)}")
print(f"Largest group size: {max(len(g) for g in groups.values())}")

# Find word pairs that could work together
# For each pair (w1, w2) in the same group, derive a mapping
# and check if it's a valid partial derangement

def derive_mapping(w1, w2):
    """Derive character mapping from w1 to w2. Returns None if not bijective."""
    if len(w1) != len(w2):
        return None
    mapping = {}
    used = set()
    for c1, c2 in zip(w1, w2):
        if c1 in mapping:
            if mapping[c1] != c2:
                return None
        else:
            if c2 in used:
                return None
            mapping[c1] = c2
            used.add(c2)
    return mapping

def mapping_compatible(m1, m2):
    """Check if two partial mappings are compatible and return merged mapping."""
    merged = dict(m1)
    used_vals = set(merged.values())
    for k, v in m2.items():
        if k in merged:
            if merged[k] != v:
                return None
        else:
            if v in used_vals or v == k:  # derangement: no char maps to itself
                return None
            merged[k] = v
            used_vals.add(v)
    # Also check derangement for m1's entries
    for k, v in merged.items():
        if v == k:
            return None
    return merged

