print(f"Found {len(candidate_pairs)} candidate word-mapping pairs")

# Now use backtracking to find a consistent set
# Sort candidates by number of unique characters they contribute (prefer more coverage)

def solve():
    candidates = candidate_pairs
    # Score candidates by character coverage
    scored = []
    for w, m in candidates:
        chars = set(w)
        scored.append((len(chars), w, m))
    scored.sort(reverse=True)

    best_words = []
    best_mapping = {}

    def backtrack(start_idx, current_words, current_mapping):
        nonlocal best_words, best_mapping
        if len(current_words) > len(best_words):
            best_words = list(current_words)
            best_mapping = dict(current_mapping)
            chars = set()
            for w in current_words:
                chars.update(w)
            if len(current_words) >= 50 and len(chars) >= 24:
                return True
        if len(current_words) >= 50:
            chars = set()
            for w in current_words:
                chars.update(w)
            if len(chars) >= 24:
                return True

        for idx in range(start_idx, len(scored)):
            _, w, m = scored[idx]
            if w in current_words:
                continue
            new_mapping = mapping_compatible(current_mapping, m)
            if new_mapping is None:
                continue
            current_words.add(w)
            if backtrack(idx + 1, current_words, new_mapping):
                return True
            current_words.remove(w)
        return False

    backtrack(0, set(), {})
    return best_words, best_mapping

print("\nSolving...")
